 import { connectMcpServer, defineAgent } from "@flue/runtime";

const curb = await connectMcpServer("curb", {
  url: "https://api.curb.numetal.xyz/mcp",
});

export default defineAgent(() => ({
  model: "anthropic/claude-sonnet-4-6",
  tools: curb.tools,
}));

